#!/usr/bin/env bash
# =============================================================================
# =============================================================================
# InstantGram v1.19.3  -  the legal links open the pages in your repository
#                     + 30 more songs, and the sheet says "use your own audio"
#   * Privacy policy and Terms of use now open the files in the repo:
#       https://github.com/Aryanshahx/instantgram/blob/main/docs/privacy.md
#       https://github.com/Aryanshahx/instantgram/blob/main/docs/terms.md
#     Nothing to publish: no GitHub Pages, no hosting. Push and the links work.
#   * Both pages are rewritten: how to delete your account and what is erased, the
#     media storage, and the music sources (Apple previews, Jamendo through Openverse).
#     The app shows the same words offline (generated lib/core/legal_text.dart).
#   * InstantGram audio: 6 new rows (Sad & soulful, Bhakti, Sufi & qawwali,
#     90s & 2000s, Wedding, EDM & drop) = 30 more songs, 70 in total.
#   * The sheet now says on every tab that you can bring your own audio from My phone.
#   * The old music brand is not named anywhere in the app any more.
# Run from the project root:   bash update_v1193_legal_music.sh
# =============================================================================
set -euo pipefail

EXPECTED_SHA256="e46b9b399de6516479752cab398062a665bd6231dcb3af9f6202a561c52d5efa"

echo "==> Checking project..."
[ -f pubspec.yaml ] || { echo "ERROR: run this from the Flutter project root (pubspec.yaml not found)."; exit 1; }
[ -f lib/services/online_music_service.dart ] || { echo "ERROR: the free music update is not installed. Run update_v1171_free_music.sh first."; exit 1; }
APP_NAME=$(grep -E '^name:' pubspec.yaml | head -1 | awk '{print $2}')

echo "==> Verifying the script (integrity check)..."
TMP_TGZ=$(mktemp /var/tmp/instantgram_payload.XXXXXX.tgz 2>/dev/null || mktemp /tmp/instantgram_payload.XXXXXX.tgz)
awk '/^__PAYLOAD__$/{f=1;next} f' "$0" | base64 -d > "$TMP_TGZ" 2>/dev/null || true
ACTUAL=$(sha256sum "$TMP_TGZ" | awk '{print $1}')
if [ "$ACTUAL" != "$EXPECTED_SHA256" ]; then
  echo "ERROR: the script file is incomplete or corrupted (checksum mismatch)."
  echo "       Download it again and retry."
  rm -f "$TMP_TGZ"; exit 1
fi

echo "==> Writing the files (your saved addresses and keys are not touched)..."
tar xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ"
chmod +x tools/merge_audio.sh signer/setup.sh 2>/dev/null || true
grep -rl "package:instantgram/" lib test 2>/dev/null | xargs -r sed -i "s#package:instantgram/#package:${APP_NAME}/#" || true

for f in lib/core/config.dart lib/core/agora_key.dart lib/core/giphy_key.dart; do
  [ -f "$f" ] || echo "    WARNING: $f is missing. Run the tools/set_*.sh script that belongs to it."
done

echo ""
echo "Done. v1.19.3 is in place."
echo ""
echo "Good to know:"
echo "  * Settings > About > Privacy policy now opens the file in your repository."
echo "  * Nothing to switch on: no GitHub Pages, no hosting, no deploy."
echo "  * The pages carry today's date and the account deletion section."
echo "  * InstantGram audio has 14 rows / 70 songs now."
exit 0

